// Define the enumeration representing possible data types
#[derive(Debug)]
enum DataType {
    ScalarInt,
    ScalarFloat,
    ScalarComplex,
    ScalarBool,
    ScalarString,
    ArrayType,
    CompositeType,
    UnknownType,
}

// Implement the function to check if the given DataType is a scalar type
fn issctype(rep: DataType) -> bool {
    match rep {
        DataType::ScalarInt | 
        DataType::ScalarFloat | 
        DataType::ScalarComplex | 
        DataType::ScalarBool | 
        DataType::ScalarString => true,
        _ => false,
    }
}

// Example usage
fn main() {
    let scalar = DataType::ScalarInt;
    let composite = DataType::CompositeType;

    println!("Is ScalarInt a scalar type? {}", issctype(scalar)); // true
    println!("Is CompositeType a scalar type? {}", issctype(composite)); // false
}